        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Table ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "tab:results",
          "kind": "ref",
          "type": "CrossRef"
        },
        {
          "text": " compares our method with three baselines on four benchmark datasets at equal wall-clock budget.",
