    {
      "children": [
        {
          "text": "Our method is best on every dataset. The largest gain, 7.2 percentage points over the best baseline, is on dataset B.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
