    },
    {
      "level": 2,
      "children": [
        {
          "text": "Limitations",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "ordered": false,
      "items": [
        {
          "children": [
            {
              "text": "Features must be standardised before fitting; unscaled inputs slow convergence.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "Only tabular data were evaluated; text and image features remain future work.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "The convergence proof needs a fixed step size and does not cover adaptive schemes.",
