      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\appendix",
      "type": "RawLatex"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Proof of the convergence rate",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
