    },
    {
      "children": [
        {
          "text": "Let ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "f",
          "type": "MathInline"
        },
        {
          "text": " be the smooth term, with gradient Lipschitz constant ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "L",
          "type": "MathInline"
        },
        {
          "text": ". The descent lemma gives",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
