    },
    {
      "latex": "f(\\beta_t) \\le f(\\beta_{t-1}) + \\langle \\nabla f(\\beta_{t-1}), \\beta_t-\\beta_{t-1}\\rangle + \\tfrac{L}{2}\\|\\beta_t-\\beta_{t-1}\\|_2^2 .",
      "numbered": true,
      "label": "eq:descent",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "Combining Equation ",
          "marks": [],
