          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Sparse regression",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Given a design matrix ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X \\in \\mathbb{R}^{n\\times d}",
          "type": "MathInline"
        },
        {
          "text": " and a response ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "y \\in \\mathbb{R}^{n}",
          "type": "MathInline"
        },
        {
          "text": ", the lasso solves",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "latex": "\\beta^{*} = \\arg\\min_{\\beta}\\ \\tfrac{1}{2}\\|X\\beta - y\\|_2^2 + \\lambda\\|\\beta\\|_1 ,",
      "numbered": true,
      "label": "eq:lasso",
      "type": "MathBlock"
    },
    {
      "children": [
        {
          "text": "with ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "\\lambda > 0",
          "type": "MathInline"
        },
        {
          "text": " controlling sparsity. Least-angle regression ",
          "marks": [],
          "type": "Text"
        },
        {
          "keys": [
            "efron2004"
          ],
          "style": "cite",
          "type": "Citation"
        },
        {
          "text": " traces the whole solution path but needs cubic time in the number of active features.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "First-order methods",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Coordinate descent ",
          "marks": [],
          "type": "Text"
        },
        {
          "keys": [
            "friedman2010"
          ],
          "style": "cite",
          "type": "Citation"
        },
        {
          "text": " and proximal gradient methods ",
          "marks": [],
          "type": "Text"
        },
        {
          "keys": [
            "beck2009"
          ],
          "style": "cite",
          "type": "Citation"
        },
        {
          "text": " avoid matrix factorisations. Accelerated proximal gradient attains the optimal ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "O(1/t^2)",
          "type": "MathInline"
        },
        {
          "text": " rate, but each iteration touches the full matrix.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Identified gap",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "No published solver combines a per-iteration cost proportional to the data sparsity with the accelerated rate and a guarantee on the selected support. Closing this gap is the aim of the thesis.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 1,
      "children": [
        {
          "text": "Methodology",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Problem formulation",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "We study Equation ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "eq:lasso",
          "kind": "eqref",
          "type": "CrossRef"
        },
        {
          "text": " under the assumption that ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X",
          "type": "MathInline"
        },
        {
          "text": " has ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "m",
          "type": "MathInline"
        },
        {
          "text": " non-zero entries, so one multiplication by ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X",
          "type": "MathInline"
        },
        {
          "text": " costs ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "O(m)",
          "type": "MathInline"
        },
        {
          "text": ". Let ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "L",
          "type": "MathInline"
        },
        {
          "text": " be the largest eigenvalue of ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X^\\top X",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "The algorithm",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Algorithm ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "alg:pgd",
          "kind": "ref",
          "type": "CrossRef"
        },
        {
          "text": " applies soft-thresholding after each gradient step of size ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "1/L",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{algorithm}[H]\n\\SetAlgoLined\n\\KwIn{$X$, $y$, $\\lambda$, step size $\\eta = 1/L$, iterations $T$}\n\\KwOut{Coefficients $\\beta_T$}\n$\\beta_0 \\leftarrow 0$\\;\n\\For{$t = 1$ \\KwTo $T$}{\n  $g_t \\leftarrow X^\\top (X\\beta_{t-1} - y)$\\;\n  $\\beta_t \\leftarrow \\mathrm{soft}(\\beta_{t-1} - \\eta g_t,\\ \\eta\\lambda)$\\;\n}\n\\caption{Proximal gradient for the lasso}\n\\label{alg:pgd}\n\\end{algorithm}",
      "type": "RawLatex"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Convergence",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "kind": "proposition",
      "title": "Convergence rate",
      "children": [
        {
          "text": "Let ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "F(\\beta)",
          "type": "MathInline"
        },
        {
          "text": " be the objective of Equation ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "eq:lasso",
          "kind": "eqref",
          "type": "CrossRef"
        },
        {
          "text": ". Then Algorithm 1 satisfies ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "F(\\beta_t)-F(\\beta^*) \\le \\dfrac{L\\|\\beta^*\\|_2^2}{2t}",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "start": true,
      "type": "Theorem"
    },
    {
      "kind": "proof",
      "title": "",
      "children": [
        {
          "text": "The bound follows from the standard descent lemma for the smooth part and the non-expansiveness of the proximal map; see Appendix ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "app:proof",
          "kind": "ref",
          "type": "CrossRef"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "start": true,
      "type": "Theorem"
    },
    {
      "children": [
        {
          "text": "Adding momentum improves the rate to ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "O(1/t^2)",
          "type": "MathInline"
        },
        {
          "text": ", at the price of one extra vector.",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
