        {
          "latex": "1",
          "type": "MathInline"
        },
        {
          "text": " that feeds a daughter ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "2",
          "type": "MathInline"
        },
        {
          "text": ", the daughter population obeys ",
