    },
    {
      "latex": "N_2(t) = N_1(0)\\,\\frac{\\lambda_1}{\\lambda_2-\\lambda_1}\\left(e^{-\\lambda_1 t} - e^{-\\lambda_2 t}\\right).",
      "numbered": true,
      "label": "eq:bateman",
