      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Summary",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "ordered": false,
      "items": [
        {
          "children": [
            {
              "text": "Decay is random for one nucleus and exponential for many.",
              "marks": [],
              "type": "Text"
            }
          ],
          "type": "ListItem"
        },
        {
          "children": [
            {
              "text": "The half-life is ln 2 divided by the decay constant.",
