          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "We study Equation ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "eq:lasso",
          "kind": "eqref",
          "type": "CrossRef"
        },
        {
          "text": " under the assumption that ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X",
          "type": "MathInline"
        },
        {
          "text": " has ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "m",
          "type": "MathInline"
        },
        {
          "text": " non-zero entries, so one multiplication by ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X",
          "type": "MathInline"
        },
        {
          "text": " costs ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "O(m)",
          "type": "MathInline"
        },
        {
          "text": ". Let ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "L",
          "type": "MathInline"
        },
        {
          "text": " be the largest eigenvalue of ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "X^\\top X",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "The algorithm",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "children": [
        {
          "text": "Algorithm ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "alg:pgd",
          "kind": "ref",
          "type": "CrossRef"
        },
        {
          "text": " applies soft-thresholding after each gradient step of size ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "1/L",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "alignment": "justify",
      "type": "Paragraph"
    },
    {
      "text": "\\begin{algorithm}[H]\n\\SetAlgoLined\n\\KwIn{$X$, $y$, $\\lambda$, step size $\\eta = 1/L$, iterations $T$}\n\\KwOut{Coefficients $\\beta_T$}\n$\\beta_0 \\leftarrow 0$\\;\n\\For{$t = 1$ \\KwTo $T$}{\n  $g_t \\leftarrow X^\\top (X\\beta_{t-1} - y)$\\;\n  $\\beta_t \\leftarrow \\mathrm{soft}(\\beta_{t-1} - \\eta g_t,\\ \\eta\\lambda)$\\;\n}\n\\caption{Proximal gradient for the lasso}\n\\label{alg:pgd}\n\\end{algorithm}",
      "type": "RawLatex"
    },
    {
      "level": 2,
      "children": [
        {
          "text": "Convergence",
          "marks": [],
          "type": "Text"
        }
      ],
      "numbered": true,
      "label": null,
      "type": "Section"
    },
    {
      "kind": "proposition",
      "title": "Convergence rate",
      "children": [
        {
          "text": "Let ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "F(\\beta)",
          "type": "MathInline"
        },
        {
          "text": " be the objective of Equation ",
          "marks": [],
          "type": "Text"
        },
        {
          "label": "eq:lasso",
          "kind": "eqref",
          "type": "CrossRef"
        },
        {
          "text": ". Then Algorithm 1 satisfies ",
          "marks": [],
          "type": "Text"
        },
        {
          "latex": "F(\\beta_t)-F(\\beta^*) \\le \\dfrac{L\\|\\beta^*\\|_2^2}{2t}",
          "type": "MathInline"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "start": true,
      "type": "Theorem"
    },
    {
      "kind": "proof",
      "title": "",
      "children": [
        {
          "text": "The bound follows from the standard descent lemma for the smooth part and the non-expansiveness of the proximal map; see Appendix ",
