          "type": "Text"
        },
        {
          "label": "app:proof",
          "kind": "ref",
          "type": "CrossRef"
        },
        {
          "text": ".",
          "marks": [],
          "type": "Text"
        }
      ],
      "start": true,
      "type": "Theorem"
    },
    {
      "children": [
        {
          "text": "Adding momentum improves the rate to ",
