      "text": "\\begin{thebibliography}{99}\n\\bibitem{tibs1996} A. Tester, Regression shrinkage and selection via a norm penalty, \\emph{J. Fictional Stat. Soc.} \\textbf{58} (1996) 267--288.\n\\bibitem{efron2004} B. Example, C. Sample and D. Placeholder, Least angle selection, \\emph{Ann. Imaginary Stat.} \\textbf{32} (2004) 407--499.\n\\bibitem{friedman2010} E. Model and F. Fitter, Regularisation paths by coordinate descent, \\emph{J. Fictional Softw.} \\textbf{33} (2010) 1--22.\n\\bibitem{beck2009} G. Prox and H. Gradient, A fast iterative shrinkage algorithm, \\emph{SIAM J. Imaging Sci. (fictional)} \\textbf{2} (2009) 183--202.\n\\end{thebibliography}",
